content:
DVM架构解析：Kernel对象的设计与实现前言Kernel是DVM中最核心的对象，它承载了从用户构图到最终执行的全部逻辑。理解Kernel的设计与实现，是深入掌握DVM的关键。本文将从架构设计、类层次结构、核心实现等角度，全面解析DVM的Kernel对象。

一、Kernel架构概览1.1 Kernel的核心职责Kernel对象在DVM中承担以下职责：
┌─────────────────────────────────────────────────────────┐│                    Kernel核心职责                        │├─────────────────────────────────────────────────────────┤│  1. 构图管理：管理元算子对象（NDObject）的生命周期        ││  2. Shape推导：Normalize阶段进行Shape正则化             ││  3. 代码生成：CodeGen阶段生成字节码指令                  ││  4. 执行管理：Launch阶段下发执行到Device                 ││  5. 内存管理：管理Workspace和UB内存分配                  │└─────────────────────────────────────────────────────────┘

1.2 Kernel类型体系DVM定义了多种Kernel类型，形成清晰的层次结构：
VKernel (抽象基类)│├── VectorKernel (Vector计算)│   └── 用于元素级操作、Reduce等│├── CubeKernel (Cube计算)│   └── 用于MatMul、GMM等矩阵运算│├── MixKernel (Cube+Vector融合)│   └── 用于MatMul后接Vector操作│├── ParallelKernel (并行堆叠)│   └── 多个Kernel并行执行│├── SequenceKernel (顺序堆叠)│   └── 多个Kernel顺序执行│├── SplitKernel (自动拆分)│   └── 根据Pattern自动拆分子Kernel│└── EagerKernel (动态图)    └── 动态图模式自动堆叠


二、VKernel基类设计2.1 类定义class VKernel &#123; public:  VKernel(KernelType ktype, uint32_t flags);  virtual ~VKernel();  // 核心虚函数  virtual void Append(NDObject *obj);           // 添加元算子  virtual void Normalize();                      // Shape推导  virtual void CodeGenR(...);                    // 代码生成（带重定位）  virtual int Launch(void *stream);              // 下发执行  virtual uint64_t CodeGen();                    // 代码生成  virtual void Dump(...);                        // Dump计算图  virtual void Clone(...);                       // 克隆Kernel  // 辅助方法  std::string &amp;DumpGraph();                      // 获取计算图字符串  virtual std::string &amp;DisAssemble();            // 反汇编字节码  KernelType KType() const;                      // 获取Kernel类型  uint32_t Flags() const;                        // 获取Kernel标志  bool IsSplit() const;                          // 是否为Split类型  bool IsDynamic() const;                        // 是否为动态Shape protected:  KernelType ktype_;                             // Kernel类型  uint32_t flags_;                               // Kernel标志  Code code_;                                    // 字节码对象  size_t pre_ws_size_;                           // Workspace大小  void *pre_ws_mem_;                             // Workspace内存  MsprofHelper *msprof_;                         // Profiling辅助  const char *op_name_;                          // 算子名称  const char *op_fullname_;                      // 算子全名  IdleCleanWrap *idle_clean_wrap_;               // 空闲清理包装  std::string dump_str_;                         // Dump字符串缓存&#125;;

2.2 核心成员解析Code对象code_是Kernel最核心的成员，存储生成的字节码：
class Code : public CodeWrap &#123; public:  enum &#123; kTargetVec = 0, kTargetCube, kTargetMix &#125;;    uint8_t *data_;           // 字节码数据指针  size_t data_size_;        // 字节码大小  uint32_t block_dim_;      // 并行Block数  int target_;              // 目标类型    // 核心方法  void Alloc(size_t size);  // 分配字节码内存  void Launch(void *workspace, void *stream);  // 执行字节码  void DisAssemble(std::ostringstream &amp;oss);   // 反汇编&#125;;

KernelType枚举enum KernelType &#123;  kVector = 0,    // 纯Vector计算  kCube,          // 纯Cube计算（MatMul）  kMix,           // Cube+Vector融合  kParallel,      // 并行堆叠  kSequence,      // 顺序堆叠  kSplit,         // 自动拆分  kEager,         // 动态图模式&#125;;

KernelFlag枚举enum KernelFlag &#123;  kDynamic = 0x1,      // 动态Shape标志  kUnifyWS = 0x2,      // 统一Workspace标志  kSpeculate = 0x4,    // 投机执行标志  kPrivate1 = 1u &lt;&lt; 30,  kPrivate2 = 1u &lt;&lt; 31,&#125;;

2.3 核心方法实现Normalize方法void VKernel::Normalize() &#123;  pre_ws_size_ = CodeGen();  // 执行代码生成并获取Workspace大小&#125;

CodeGenR方法（带重定位）void VKernel::CodeGenR(const RelocEntry *relocs, size_t reloc_size,                        WsAllocator *ws_alloc) &#123;  // 1. 重定位地址  auto reloc = relocs;  for (size_t i = 0; i &lt; reloc_size; ++i, ++reloc) &#123;    static_cast&lt;NDAccess *&gt;(reloc-&gt;io)-&gt;addr_.Reloc(reloc-&gt;addr);  &#125;    // 2. Profiling处理  if (g_system.enable_profile_) &#123;    // 初始化或更新Profiling信息    ...  &#125;    // 3. 分配Workspace  if (ws_alloc) &#123;    pre_ws_mem_ = ws_alloc-&gt;Alloc(pre_ws_size_);  &#125;&#125;

Launch方法int VKernel::Launch(void *stream) &#123;  // 1. 重定位绑定  code_.RelocBinds(pre_ws_mem_);    // 2. 执行字节码  if (likely(!g_system.enable_profile_ || msprof_ == nullptr)) &#123;    return code_.Launch(pre_ws_mem_, stream);  &#125; else &#123;    // 带Profiling的执行    _MsprofLaunchGuard guard(code_, msprof_);    return code_.Launch(pre_ws_mem_, stream);  &#125;&#125;


三、VectorKernel实现3.1 类定义class VectorKernel : public VKernel &#123; public:  explicit VectorKernel(KernelType ktype, uint32_t flags);    void Dump(std::ostringstream &amp;oss, const std::string &amp;indent) override;    // 核心方法  void BuildDomain();        // 构建计算域  void PrepareTiling();      // 准备Tiling策略    // 代码生成  uint8_t *DoCodeGen(uint64_t core_limit, uint8_t *code_ptr,                      uint64_t code_reserve);  uint64_t DoCodeGen(uint64_t core_limit);  uint64_t DoCodeGenInner(uint64_t core_limit);    // Tiling相关  void Shard(const ShardParam &amp;sp);  void SetTile(int start, int end, int64_t num, int64_t factor);    // 辅助方法  uint64_t ReserveCodeSize() const;  uint32_t CompactBlockDim(uint64_t core_limit);  NDAccess *FindInplaceStore(...);  void CollectIdle(std::vector&lt;NDObject *&gt; &amp;cleans);  void ProcessIdle(); protected:  std::vector&lt;NDObject *&gt; objects_;      // 元算子对象列表  std::vector&lt;NDObject *&gt; static_ops_;   // 静态算子列表  Domain *dom_;                          // 计算域  uint64_t tile_num_;                    // Tile数量  uint64_t tile_size_;                   // Tile大小  uint64_t xbuf_size_;                   // UB缓冲区大小  int max_type_;                         // 最大数据类型  int min_type_;                         // 最小数据类型  uint64_t lead_align_;                  // 前导对齐  CommOp *comm_op_;                      // 通信算子  const ShardParam *shard_;              // 分片参数  std::vector&lt;DimTile&gt; tiles_;           // Tile配置&#125;;

3.2 核心实现DoCodeGen方法uint64_t VectorKernel::DoCodeGen(uint64_t core_limit) &#123;  // 1. 准备Tiling  PrepareTiling();    // 2. 处理空Kernel  if (unlikely(!tile_size_)) &#123;    ProcessIdle();    return 0;  &#125;    // 3. 执行内部代码生成  return DoCodeGenInner(core_limit);&#125;uint64_t VectorKernel::DoCodeGenInner(uint64_t core_limit) &#123;  // 1. 预留代码空间  auto code_reserve = ReserveCodeSize();  code_.Alloc(code_reserve + code_.HeadSize());    // 2. 生成代码  auto code_end = DoCodeGen(core_limit, code_.data_ + code_.HeadSize(),                             code_reserve);  code_.data_size_ = code_end - code_.data_;    // 3. 更新Block维度  if (auto visit = GetVisitor&lt;RedVisitCoder&gt;(); visit != nullptr) &#123;    code_.block_dim_ = CeilDiv&lt;uint32_t&gt;(visit-&gt;block_num_, 2);    code_.UpdateVE(visit);    return visit-&gt;ws_size_;  &#125;    code_.block_dim_ = CompactBlockDim(core_limit);  code_.UpdateV(tile_num_);  return 0;&#125;

PrepareTiling方法void VectorKernel::PrepareTiling() &#123;  // 1. 构建计算域  BuildDomain();    // 2. 计算Tile参数  auto &amp;dims = dom_-&gt;nd_.dims();  tile_num_ = 1;  tile_size_ = 1;    for (size_t i = 0; i &lt; dims.size(); ++i) &#123;    tile_num_ *= dims[i];  &#125;    // 3. 根据数据类型计算Tile大小  tile_size_ = CalculateTileSize(max_type_);  xbuf_size_ = tile_size_ * ITEM_SIZE[max_type_];&#125;

ReserveCodeSize方法uint64_t VectorKernel::ReserveCodeSize() const &#123;  // 基础大小 + 每个算子的指令大小  auto res = SIMD_BLOCK_SIZE + objects_.size() * V_INSN_SIZE_MAX;    // 通信算子额外空间  if (comm_op_) &#123;    res += comm_op_-&gt;CodeReserve();  &#125;    // 512字节对齐  return (res + 511ul) &amp; ~511ul;&#125;


四、CubeKernel实现4.1 类定义class CubeKernel : public VKernel &#123; public:  CubeKernel(KernelType ktype, uint32_t flags);  ~CubeKernel() override;    void Append(NDObject *obj) override;  void Dump(std::ostringstream &amp;oss, const std::string &amp;indent) override;  void Clone(VKernel *base, CloneHelper &amp;helper) override;    uint64_t CodeGen() override;  uint8_t *DoCodeGen(uint8_t *code_ptr, uint64_t core_limit); protected:  CubeOp *cube_op_;       // Cube算子对象  bool reload_rhs_;       // 是否重新加载右矩阵  Tuner *tuner_;          // 调优器&#125;;

4.2 核心实现Append方法void CubeKernel::Append(NDObject *obj) &#123;  if (obj-&gt;IsCube()) &#123;    cube_op_ = static_cast&lt;CubeOp *&gt;(obj);        // 处理左右矩阵相同的情况    if (cube_op_-&gt;lhs_ == cube_op_-&gt;rhs_) &#123;      auto lhs = static_cast&lt;NDAccess *&gt;(cube_op_-&gt;lhs_);      cube_op_-&gt;rhs_ = new NDLoad(nullptr, lhs-&gt;shape_ref_, lhs-&gt;type_id_);      reload_rhs_ = true;    &#125;  &#125; else if (obj-&gt;IsStore() &amp;&amp; obj-&gt;lhs_ == cube_op_) &#123;    cube_op_-&gt;output_ = static_cast&lt;NDAccess *&gt;(obj);  &#125;&#125;

DoCodeGen方法uint8_t *CubeKernel::DoCodeGen(uint8_t *code_ptr, uint64_t core_limit) &#123;  ASSERT(cube_op_-&gt;output_ != nullptr);    // 1. 生成Cube指令  vCubeOp *cube_code = reinterpret_cast&lt;vCubeOp *&gt;(code_ptr);  cube_op_-&gt;CodeGen(cube_code, tuner_);    // 2. 绑定地址  static_cast&lt;NDAccess *&gt;(cube_op_-&gt;lhs_)-&gt;addr_.Update(&amp;cube_code-&gt;gm_a);  static_cast&lt;NDAccess *&gt;(cube_op_-&gt;rhs_)-&gt;addr_.Update(&amp;cube_code-&gt;gm_b);    if (cube_code-&gt;flags &amp; V_CUBE_FLAG_WITH_BIAS) &#123;    static_cast&lt;NDAccess *&gt;(cube_op_-&gt;bias_)-&gt;addr_.Update(&amp;cube_code-&gt;gm_bias);  &#125;    cube_op_-&gt;output_-&gt;addr_.Update(&amp;cube_code-&gt;gm_c);    // 3. 设置Block维度  code_.block_dim_ = std::min(cube_op_-&gt;block_dim_, core_limit);    return code_ptr + sizeof(vCubeOp);&#125;


五、MixKernel实现5.1 设计思想MixKernel实现Cube计算与后续Vector计算的融合：
传统方式：MatMul → 写回GM → 读入UB → Bias → Scale → Store         (多次GM访问，性能差)Mix融合：MatMul → [L1 Cache] → Bias → Scale → Store         (Cube和Vector在Tile粒度Overlap)

5.2 类定义class MixKernelBase : public CubeKernel &#123; public:  MixKernelBase(KernelType ktype, uint32_t flags);  ~MixKernelBase() override;    void Append(NDObject *obj) override;  uint64_t CodeGen() override; protected:  VKernel *post_fusion_;              // 后融合Vector Kernel  NDLoad *sload_;                     // 从Cube加载的伪Load  std::vector&lt;std::pair&lt;NDLoad*, NDAccess*&gt;&gt; reloads_;  // 重载列表&#125;;

5.3 Append方法实现void MixKernelBase::Append(NDObject *obj) &#123;  constexpr uint32_t LOAD_VEC_USED = 0;  constexpr uint32_t LOAD_PENDING = 1;  constexpr uint32_t LOAD_CUBE_USED = 2;    if (obj-&gt;IsLoad()) &#123;    obj-&gt;xbuf_ = LOAD_PENDING;  &#125; else if (obj-&gt;IsCube()) &#123;    // 处理Cube算子    EXCEPTION_IF(cube_op_ != nullptr, &quot;only one cube op in mix-kernel&quot;);    CubeKernel::Append(obj);    obj-&gt;lhs_-&gt;xbuf_ = LOAD_CUBE_USED;    obj-&gt;rhs_-&gt;xbuf_ = LOAD_CUBE_USED;  &#125; else if (obj-&gt;IsStore() &amp;&amp; obj-&gt;lhs_ == cube_op_) &#123;    cube_op_-&gt;output_ = static_cast&lt;NDAccess *&gt;(obj);  &#125; else &#123;    // 处理后融合Vector算子    if (post_fusion_ == nullptr) &#123;      post_fusion_ = IsDynamic() ? new VKernelD() : new VKernelS();    &#125;        // 替换Cube输出为伪Load    obj-&gt;ForInput([this](NDObject *&amp;op) &#123;      if (op == cube_op_) &#123;        if (sload_ == nullptr) &#123;          sload_ = new NDLoad(nullptr, cube_op_-&gt;shape_ref_, cube_op_-&gt;type_id_);          sload_-&gt;flags_ |= OBJ_FLAG_LOAD_FROM_CUBE;          post_fusion_-&gt;Append(sload_);        &#125;        op = sload_;      &#125; else if (op-&gt;IsLoad() &amp;&amp; op-&gt;xbuf_ != LOAD_VEC_USED) &#123;        // 处理其他Load        ...      &#125;    &#125;);        post_fusion_-&gt;Append(obj);  &#125;&#125;


六、堆叠Kernel实现6.1 ParallelKernel并行堆叠多个子Kernel到不同核心执行：
class ParallelKernel : public VKernel &#123; public:  void Append(NDObject *obj) override;  uint64_t CodeGen() override;  int Launch(void *stream) override; private:  std::vector&lt;VKernel *&gt; sub_kernels_;    // 子Kernel列表  std::vector&lt;uint32_t&gt; core_limits_;     // 核心数限制&#125;;

使用场景：
// 两个独立计算并行执行k.ParallelAdd(dvm::kVector);// ... Vector计算 ...k.ParallelAdd(dvm::kCube);// ... Cube计算 ...

6.2 SequenceKernel顺序堆叠多个子Kernel：
class SequenceKernel : public VKernel &#123; public:  void Append(NDObject *obj) override;  uint64_t CodeGen() override;  int Launch(void *stream) override; private:  std::vector&lt;VKernel *&gt; sub_kernels_;    // 子Kernel列表  std::vector&lt;NDAccess *&gt; intermediates_; // 中间结果&#125;;

特点：

自动插入Load&#x2F;Store处理中间结果
降低运行时调度开销

6.3 SplitKernel自动拆分复杂计算图：
class SplitKernel : public VKernel &#123; public:  void Append(NDObject *obj) override;  uint64_t CodeGen() override; private:  void SplitGraph();                      // 拆分计算图  std::vector&lt;VKernel *&gt; sub_kernels_;    // 拆分后的子Kernel&#125;;

拆分规则：

Cube算子单独拆分
通信算子单独拆分
相邻Vector算子合并

6.4 EagerKernel动态图模式的自动堆叠：
class EagerKernel : public SplitKernel &#123; public:  void Clear();    // 清理状态，准备下一次构图&#125;;

特点：

每次执行后可重新构图
支持动态图场景


七、Kernel生命周期7.1 静态Shape流程┌──────────┐    ┌──────────┐    ┌──────────┐    ┌──────────┐│  Reset   │ -&gt; │  Append  │ -&gt; │Normalize │ -&gt; │ CodeGen  │└──────────┘    └──────────┘    └──────────┘    └──────────┘                                                      │                                                      v┌──────────┐    ┌──────────┐    ┌──────────┐    ┌──────────┐│  完成    │ &lt;- │ 多次执行  │ &lt;- │  Launch  │ &lt;- │ 缓存代码  │└──────────┘    └──────────┘    └──────────┘    └──────────┘

7.2 动态Shape流程┌──────────┐    ┌──────────┐│  Reset   │ -&gt; │  Append  │└──────────┘    └──────────┘                      │                      v              ┌──────────────┐              │  首次执行    │ &lt;─────────────┐              └──────────────┘               │                      │                       │                      v                       │              ┌──────────────┐               │              │  Normalize   │               │              └──────────────┘               │                      │                       │                      v                       │              ┌──────────────┐               │              │   CodeGen    │               │              └──────────────┘               │                      │                       │                      v                       │              ┌──────────────┐               │              │   Launch     │               │              └──────────────┘               │                      │                       │                      v                       │              ┌──────────────┐               │              │ 更新Shape    │ ──────────────┘              └──────────────┘


八、内存管理8.1 Workspace管理class WsAllocator &#123; public:  virtual void *Alloc(size_t size) = 0;&#125;;// Device端实现class DevRunner : public KernelRunner &#123;  void *Alloc(size_t size) override &#123;    void *ws = nullptr;    if (size &gt; 0) &#123;      aclrtMalloc(&amp;ws, size, ACL_MEM_TYPE_HIGH_BAND_WIDTH);      dev_mem_.push_back(ws);    &#125;    return ws;  &#125;&#125;;

8.2 UB内存管理VectorKernel通过xbuf管理UB内存：
// xbuf分配策略for (auto op : objects_) &#123;  if (op-&gt;IsLoad()) &#123;    op-&gt;xbuf_ = static_xbuf_;  &#125; else &#123;    op-&gt;lhs_-&gt;xbuf_ = static_xbuf_;  &#125;    // 根据数据类型分配空间  if (op-&gt;type_id_ != max_type_) &#123;    static_xbuf_ += tile_size_ * ITEM_SIZE[op-&gt;type_id_];  &#125; else &#123;    static_xbuf_ += xbuf_size_;  &#125;&#125;


九、总结本文详细解析了DVM Kernel对象的设计与实现：

VKernel基类：定义了Kernel的核心接口和生命周期
VectorKernel：实现Vector计算的代码生成和执行
CubeKernel：实现MatMul等矩阵运算
MixKernel：实现Cube和Vector的融合执行
堆叠Kernel：Parallel、Sequence、Split、Eager实现多Kernel组合
内存管理：Workspace和UB内存的高效管理

理解Kernel的设计，是深入DVM源码的关键一步。下一篇将详细介绍元算子系统的实现。

参考资料
kernel.h
kernel.cc
xkernel.h
xkernel.cc

DVM元算子系统：NDObject与计算图构建前言在DVM中，元算子系统是用户构图的基础。用户通过Load、Store、Binary、Unary等元算子API构建计算图，这些元算子在内部被表示为NDObject对象。本文将深入解析DVM的元算子系统，揭示计算图构建的内部机制。

一、元算子概述1.1 什么是元算子元算子是DVM定义的最小计算单元，类似于CPU指令集。DVM的元算子包括：
┌─────────────────────────────────────────────────────────┐│                    元算子分类                            │├─────────────────────────────────────────────────────────┤│  访存类：Load, Store, ViewLoad, PadStore              ││  一元类：Sqrt, Abs, Log, Exp, Reciprocal, Cast        ││  二元类：Add, Sub, Mul, Div, Pow, Maximum, Minimum    ││  归约类：Sum, Max, Min                                ││  矩阵类：MatMul, GroupedMatMul                         ││  形状类：Reshape, Broadcast, Copy                     ││  条件类：Select                                         ││  通信类：AllReduce, AllGather, ReduceScatter          │└─────────────────────────────────────────────────────────┘

1.2 元算子特点
细粒度：每个元算子对应一个具体的计算操作
可组合：多个元算子可以组合成复杂的融合算子
类型安全：支持多种数据类型，编译时类型检查
Shape推导：自动进行Shape广播和推导


二、NDObject核心类2.1 类层次结构// 基类class NDObject &#123;  ObjectType obj_id_;       // 对象类型  DataType type_id_;        // 数据类型  IntArrayRef *shape_ref_;  // Shape引用  NDSpace nd_;              // N维空间信息  uint64_t xbuf_;           // UB缓冲区偏移  uint64_t index_;          // 对象索引  uint32_t flags_;          // 标志位    NDObject *lhs_;           // 左输入  NDObject *rhs_;           // 右输入  uint64_t *insn_;          // 指令指针  uint64_t *tail_insn_;     // 尾指令指针&#125;;// 访存类class NDAccess : public NDObject &#123;  RelocAddr addr_;          // 重定位地址&#125;;class NDLoad : public NDAccess &#123; ... &#125;;class NDStore : public NDAccess &#123; ... &#125;;// 计算类class NDSimd : public NDObject &#123; ... &#125;;class NDBinary : public NDSimd &#123; ... &#125;;class NDUnary : public NDSimd &#123; ... &#125;;class NDFlex : public NDSimd &#123; ... &#125;;  // Reduce等// 矩阵类class CubeOp : public NDObject &#123; ... &#125;;class GmmOp : public CubeOp &#123; ... &#125;;// 通信类class CommOp : public NDSimd &#123; ... &#125;;

2.2 ObjectType枚举enum ObjectType &#123;  // Load类型  kLoadDummy = 0,  kMultiLoad,  kViewLoad,  kLoad,    // Store类型  kPadStore,  kStore,    // 通信类型  kReduceScatter,  kAllGather,  kAllGatherV2,  kAllReduce,    // SIMD计算类型  kReshape,  kCopy,  kUnary,  kBinary,  kCast,  kBinaryS,  kBroadcastTo,  kBroadcastS,  kReduce,  kSelect,  kElementAny,  kRemovePad,  kPower,  kCompare,  kCompareS,  kOneHot,  kCubeOp,  kGmmOp,  kObjectBulk&#125;;

2.3 核心成员解析NDSpace - N维空间class NDSpace &#123;  const NDSpaceData *data;  // 指向空间数据    int64_t operator[](int i) const;     // 获取维度大小  int64_t stride(int i) const;         // 获取步长  int64_t lead_dim() const;            // 获取前导维度  int64_t lead_stride() const;         // 获取前导步长  const DimArray &amp;dims() const;        // 获取维度数组&#125;;class NDSpaceData &#123;  DimArray dims;      // 维度数组  DimArray strides;   // 步长数组  int lidx;           // 前导维度索引&#125;;

RelocAddr - 重定位地址struct RelocAddr &#123;  union &#123;    void *gm;           // 全局内存地址    uint64_t ws;        // Workspace偏移    const RelocAddr *op;// 指向其他地址    uint64_t data;      // 数据值  &#125;;  uint64_t *reloc_;     // 重定位指针    void Reloc(void *dst) &#123;    if (reloc_) &#123;      *reloc_ = reinterpret_cast&lt;uint64_t&gt;(dst);    &#125;  &#125;&#125;;


三、元算子实现详解3.1 Load算子Load算子从全局内存加载数据到UB：
class NDLoad : public NDAccess &#123; public:  NDLoad(void *addr, IntArrayRef *shape, DataType type) &#123;    obj_id_ = kLoad;    type_id_ = type;    shape_ref_ = shape;    addr_.gm = addr;        // 初始化NDSpace    UpdateShape();  &#125;    void UpdateShape() &#123;    // 从shape_ref_更新nd_    nd_.data = &amp;space_data_;    space_data_.dims = *shape_ref_;        // 计算步长    UpdateStrides();  &#125;    void UpdateStrides() &#123;    auto &amp;dims = space_data_.dims;    auto &amp;strides = space_data_.strides;        strides.resize(dims.size());    strides.back() = 1;        for (int i = dims.size() - 2; i &gt;= 0; --i) &#123;      strides[i] = strides[i + 1] * dims[i + 1];    &#125;        // 找到前导维度    space_data_.lidx = 0;    for (size_t i = 0; i &lt; dims.size(); ++i) &#123;      if (dims[i] != 1) &#123;        space_data_.lidx = i;        break;      &#125;    &#125;  &#125;&#125;;

