3.2 Store算子Store算子将结果存储回全局内存：
class NDStore : public NDAccess &#123; public:  NDStore(void *addr, NDObject *input) &#123;    obj_id_ = kStore;    type_id_ = input-&gt;type_id_;    shape_ref_ = input-&gt;shape_ref_;    lhs_ = input;    addr_.gm = addr;  &#125;&#125;;

3.3 Binary算子Binary算子实现二元计算：
class NDBinary : public NDSimd &#123; public:  NDBinary(BinaryType op_type, NDObject *lhs, NDObject *rhs) &#123;    obj_id_ = kBinary;    lhs_ = lhs;    rhs_ = rhs;    op_type_ = op_type;        // Shape推导    PropShape();    PropType();  &#125;    void PropShape() &#123;    // 广播Shape推导    auto &amp;lhs_shape = lhs_-&gt;nd_.dims();    auto &amp;rhs_shape = rhs_-&gt;nd_.dims();        // 取最大Shape    size_t max_rank = std::max(lhs_shape.size(), rhs_shape.size());        for (size_t i = 0; i &lt; max_rank; ++i) &#123;      int64_t lhs_dim = i &lt; lhs_shape.size() ?                    lhs_shape[lhs_shape.size() - 1 - i] : 1;      int64_t rhs_dim = i &lt; rhs_shape.size() ?                    rhs_shape[rhs_shape.size() - 1 - i] : 1;            if (lhs_dim != rhs_dim &amp;&amp; lhs_dim != 1 &amp;&amp; rhs_dim != 1) &#123;        // Shape不兼容        throw std::runtime_error(&quot;Incompatible shapes&quot;);      &#125;            result_shape_.push_front(std::max(lhs_dim, rhs_dim));    &#125;  &#125;    void PropType() &#123;    // 类型推导    type_id_ = std::max(lhs_-&gt;type_id_, rhs_-&gt;type_id_);  &#125;   private:  BinaryType op_type_;&#125;;

