3.5 Reduce算子Reduce算子实现归约计算：
class NDFlex : public NDSimd &#123; public:  // Reduce构造函数  NDFlex(ReduceType red_type, NDObject *input,          IntArrayRef *dims, bool keepdims) &#123;    obj_id_ = kReduce;    lhs_ = input;    red_type_ = red_type;    reduce_dims_ = *dims;    keepdims_ = keepdims;        // Shape推导    PropReduceShape();  &#125;    void PropReduceShape() &#123;    auto &amp;input_shape = lhs_-&gt;nd_.dims();    result_shape_.clear();        std::unordered_set&lt;int64_t&gt; reduce_set;    for (auto dim : reduce_dims_) &#123;      reduce_set.insert(dim &lt; 0 ? input_shape.size() + dim : dim);    &#125;        for (size_t i = 0; i &lt; input_shape.size(); ++i) &#123;      if (reduce_set.count(i)) &#123;        if (keepdims_) &#123;          result_shape_.push_back(1);        &#125;      &#125; else &#123;        result_shape_.push_back(input_shape[i]);      &#125;    &#125;  &#125;   private:  ReduceType red_type_;  DimArray reduce_dims_;  bool keepdims_;&#125;;

