3.6 MatMul算子MatMul算子实现矩阵乘法：
class CubeOp : public NDObject &#123; public:  CubeOp(NDObject *lhs, NDObject *rhs,          bool trans_a, bool trans_b, NDObject *bias) &#123;    obj_id_ = kCubeOp;    lhs_ = lhs;    rhs_ = rhs;    bias_ = bias;    trans_a_ = trans_a;    trans_b_ = trans_b;        // Shape推导    PropMatMulShape();  &#125;    void PropMatMulShape() &#123;    auto &amp;lhs_shape = lhs_-&gt;nd_.dims();    auto &amp;rhs_shape = rhs_-&gt;nd_.dims();        // M = lhs_shape[-2] (or -1 if trans_a)    // K = lhs_shape[-1] (or -2 if trans_a)    // N = rhs_shape[-1] (or -2 if trans_b)        int64_t M = trans_a_ ? lhs_shape.back() : lhs_shape[lhs_shape.size() - 2];    int64_t N = trans_b_ ? rhs_shape[rhs_shape.size() - 2] : rhs_shape.back();        // Batch维度    for (size_t i = 0; i &lt; lhs_shape.size() - 2; ++i) &#123;      result_shape_.push_back(lhs_shape[i]);    &#125;        result_shape_.push_back(M);    result_shape_.push_back(N);  &#125;   private:  bool trans_a_;  bool trans_b_;  NDObject *bias_;  NDAccess *output_;  NDAccess *lhs_;  NDAccess *rhs_;  int block_dim_;  int core_loop_;&#125;;


四、计算图构建4.1 KernelBuilder辅助类class KernelBuilder &#123; public:  KernelBuilder(VKernel *kernel) : kernel_(kernel) &#123;&#125;    NDObject *Load(void *addr, IntArrayRef *shape, DataType type) &#123;    auto op = new NDLoad(addr, shape, type);    kernel_-&gt;Append(op);    return op;  &#125;    NDObject *Store(void *addr, NDObject *input) &#123;    auto op = new NDStore(addr, input);    kernel_-&gt;Append(op);    return op;  &#125;    template &lt;BinaryType BT&gt;  NDObject *Binary(NDObject *lhs, NDObject *rhs) &#123;    auto op = new NDBinary(BT, lhs, rhs);    kernel_-&gt;Append(op);    return op;  &#125;    template &lt;UnaryType UT&gt;  NDObject *Unary(NDObject *input) &#123;    auto op = new NDUnary(UT, input);    kernel_-&gt;Append(op);    return op;  &#125;    template &lt;ReduceType RT&gt;  NDObject *Reduce(NDObject *input, IntArrayRef *dims, bool keepdims) &#123;    auto op = new NDFlex(RT, input, dims, keepdims);    kernel_-&gt;Append(op);    return op;  &#125;   private:  VKernel *kernel_;&#125;;

