五、Shape推导系统5.1 广播规则void PropBroadcastShape(const DimArray &amp;lhs, const DimArray &amp;rhs,                         DimArray &amp;result) &#123;  size_t max_rank = std::max(lhs.size(), rhs.size());  result.resize(max_rank);    for (size_t i = 0; i &lt; max_rank; ++i) &#123;    int64_t lhs_dim = i &lt; lhs.size() ? lhs[lhs.size() - 1 - i] : 1;    int64_t rhs_dim = i &lt; rhs.size() ? rhs[rhs.size() - 1 - i] : 1;        if (lhs_dim == rhs_dim) &#123;      result[max_rank - 1 - i] = lhs_dim;    &#125; else if (lhs_dim == 1) &#123;      result[max_rank - 1 - i] = rhs_dim;    &#125; else if (rhs_dim == 1) &#123;      result[max_rank - 1 - i] = lhs_dim;    &#125; else &#123;      throw std::runtime_error(&quot;Broadcast error&quot;);    &#125;  &#125;&#125;

5.2 隐式广播插入DVM会自动插入Broadcast操作：
NDObject *InsertImplicitBroadcast(NDObject *obj, const DimArray &amp;dst_shape,                                  std::vector&lt;NDObject *&gt; &amp;stuff_ops) &#123;  // 逐步插入Broadcast  auto temp_shape = obj-&gt;nd_.dims();  NDObject *output = obj;    for (size_t i = 0; i &lt; temp_shape.size(); ++i) &#123;    if (temp_shape[i] != dst_shape[i]) &#123;      temp_shape[i] = dst_shape[i];      output = new BroadcastOp(output, temp_shape);      stuff_ops.push_back(output);    &#125;  &#125;    return output;&#125;


