DVM编译优化：图优化Pass实现前言DVM的编译优化阶段通过一系列图优化Pass对计算图进行变换，以提升性能、减少内存占用。本文将深入解析DVM的图优化Pass实现，包括ReorderStore、ReorderLoad、CompactPeakLiveness、EliminateReshape等核心优化。

一、图优化概述1.1 优化目标DVM图优化的主要目标：
┌─────────────────────────────────────────────────────────┐│                  图优化目标                              │├─────────────────────────────────────────────────────────┤│  1. 减少内存占用：降低活跃变量峰值                      ││  2. 提升数据局部性：优化访存模式                        ││  3. 消除冗余操作：去除无用的Reshape等                   ││  4. 优化执行顺序：重排算子执行顺序                      │└─────────────────────────────────────────────────────────┘

1.2 Pass框架namespace dvm::pass &#123;// Pass类型定义using Pass = void (*)(BasicBlock &amp;);// 全局Pass列表extern std::vector&lt;Pass&gt; passes;// 核心Pass函数void ReorderStore(BasicBlock &amp;block);      // 重排Storevoid ReorderLoad(BasicBlock &amp;block);       // 重排Loadvoid CompactPeakLiveness(BasicBlock &amp;bb);  // 压缩活跃变量峰值void EliminateReshape(BasicBlock &amp;bb);     // 消除Reshapevoid InsertRemovePad(BasicBlock &amp;block);   // 插入RemovePad&#125;  // namespace dvm::pass


二、BasicBlock数据结构2.1 核心类定义class BasicBlock &#123; public:  // 边结构：表示用户关系  struct Edge &#123;    int64_t next;      // 下一条边的索引    NDObject *user;    // 用户节点  &#125;;    // 迭代器类型  using iterator = ObjectList::Iterator&lt;false&gt;;  using reverse_iterator = ObjectList::Iterator&lt;true&gt;;    // 构造函数  BasicBlock(const std::vector&lt;NDObject *&gt; &amp;objects,              std::vector&lt;NDObject *&gt; &amp;owner,             GraphTracker *tracker = nullptr);    // 迭代器  iterator begin() &#123; return iterator(list_.Begin()); &#125;  iterator end() &#123; return iterator(list_.End()); &#125;  reverse_iterator rbegin() &#123; return reverse_iterator(list_.ReverseBegin()); &#125;  reverse_iterator rend() &#123; return reverse_iterator(list_.ReverseEnd()); &#125;    // 大小  size_t size() const &#123; return list_.size_; &#125;  size_t capacity() const &#123; return list_.capacity_; &#125;    // 修改操作  iterator Insert(iterator iter, NDObject *object);  void Erase(NDObject *object);  iterator Move(iterator iter, NDObject *object);  void UpdateInput(NDObject *obj, NDObject *old, NDObject *update);    // 便捷方法  void PushFront(NDObject *ptr) &#123; Insert(begin(), ptr); &#125;  void PushBack(NDObject *ptr) &#123; Insert(end(), ptr); &#125;    // 用户查询  std::vector&lt;NDObject *&gt; GetUsers(NDObject *object) const;  size_t GetUserNum(NDObject *object) const;  bool IsMultiUsers(NDObject *object) const;    // 添加用户  void AddUser(NDObject *obj, NDObject *new_user);    // 导出  void Export(std::vector&lt;NDObject *&gt; &amp;objects);   private:  static int GetHead(NDObject *obj) &#123; return obj-&gt;xbuf_; &#125;  static void SetHead(NDObject *obj, int head) &#123; obj-&gt;xbuf_ = head; &#125;    ObjectList list_;                    // 对象列表  std::vector&lt;Edge&gt; edges_;            // 边列表  std::vector&lt;NDObject *&gt; &amp;objects_owner_;  // 对象所有者  GraphTracker *tracker_;              // 图追踪器&#125;;

2.2 ObjectList实现class ObjectList &#123; public:  ObjectList() : sentinel_(kDataTypeEnd) &#123;&#125;    void Build(const std::vector&lt;NDObject *&gt; &amp;objects, bool reindex);    void Insert(NDObject *pos, NDObject *obj) &#123;    auto prev = Prev(pos);    SetNext(obj, prev);    SetPrev(obj, pos);    SetPrev(pos, obj);    SetNext(prev, obj);    size_++;    obj-&gt;index_ = capacity_++;  &#125;    void Erase(NDObject *obj) &#123;    auto prev = Prev(obj);    auto next = Next(obj);    SetNext(prev, next);    SetPrev(next, prev);    size_--;  &#125;    NDObject *Begin() &#123; return Next(&amp;sentinel_); &#125;  NDObject *End() &#123; return &amp;sentinel_; &#125;  NDObject *ReverseBegin() &#123; return Prev(&amp;sentinel_); &#125;  NDObject *ReverseEnd() &#123; return &amp;sentinel_; &#125;    // 使用insn_和tail_insn_作为前后指针  static NDObject *Next(NDObject *obj) &#123;     return reinterpret_cast&lt;NDObject *&gt;(obj-&gt;insn_);   &#125;  static NDObject *Prev(NDObject *obj) &#123;     return reinterpret_cast&lt;NDObject *&gt;(obj-&gt;tail_insn_);   &#125;  static void SetNext(NDObject *obj, NDObject *next) &#123;     obj-&gt;insn_ = reinterpret_cast&lt;uint64_t *&gt;(next);   &#125;  static void SetPrev(NDObject *obj, NDObject *prev) &#123;     obj-&gt;tail_insn_ = reinterpret_cast&lt;uint64_t *&gt;(prev);   &#125;   private:  NDLoadDummy sentinel_;  // 哨兵节点  size_t size_;  size_t capacity_;&#125;;

2.3 用户关系图BasicBlock使用边列表维护用户关系：
// 添加用户void AddUser(NDObject *obj, NDObject *new_user) &#123;  edges_.push_back(&#123;GetHead(obj), new_user&#125;);  SetHead(obj, static_cast&lt;int&gt;(edges_.size() - 1));&#125;// 获取用户列表std::vector&lt;NDObject *&gt; GetUsers(NDObject *object) const &#123;  std::vector&lt;NDObject *&gt; res;  for (auto idx = GetHead(object); idx != -1; idx = edges_[idx].next) &#123;    res.push_back(edges_[idx].user);  &#125;  return res;&#125;// 判断是否有多个用户bool IsMultiUsers(NDObject *object) const &#123;  auto idx = GetHead(object);  return idx != -1 &amp;&amp; edges_[idx].next != -1;&#125;


三、ReorderStore优化3.1 优化原理ReorderStore通过重排Store操作来减少活跃变量峰值：
优化前：%0 = Load()%1 = Load()%2 = Binary(%0, %1)%3 = Binary(%0, %1)%4 = Store(%3)    &lt;- %2仍然活跃%5 = Store(%2)优化后：%0 = Load()%1 = Load()%2 = Binary(%0, %1)%5 = Store(%2)    &lt;- 先存储%2，释放内存%3 = Binary(%0, %1)%4 = Store(%3)

3.2 实现代码void ReorderStore(BasicBlock &amp;block) &#123;  // 遍历所有Store操作  for (auto iter = block.begin(); iter != block.end(); ++iter) &#123;    auto obj = &amp;*iter;    if (!obj-&gt;IsStore()) continue;        // 获取Store的输入    auto input = obj-&gt;lhs_;    if (input == nullptr || input-&gt;IsLoad()) continue;        // 检查是否是唯一消费者    if (block.IsMultiUsers(input)) continue;        // 找到input的定义位置    auto input_iter = block.begin();    for (; input_iter != block.end(); ++input_iter) &#123;      if (&amp;*input_iter == input) break;    &#125;        // 找到下一个Store的位置    auto next_store = iter;    ++next_store;    for (; next_store != block.end(); ++next_store) &#123;      if (next_store-&gt;IsStore()) break;    &#125;        if (next_store == block.end()) continue;        // 检查是否可以移动    // 条件：input在iter和next_store之间没有被使用    bool can_move = true;    for (auto check = iter; check != next_store; ++check) &#123;      if (&amp;*check == input) continue;            // 检查是否使用了input      bool uses_input = false;      check-&gt;ForInput([&amp;input, &amp;uses_input](NDObject *op) &#123;        if (op == input) uses_input = true;      &#125;);            if (uses_input) &#123;        can_move = false;        break;      &#125;    &#125;        if (can_move) &#123;      // 移动Store到前面      block.Move(next_store, obj);    &#125;  &#125;&#125;


四、ReorderLoad优化4.1 优化原理ReorderLoad将Load操作移动到最早使用位置之前，提升数据局部性：
优化前：%0 = Load()%1 = Load()%2 = Unary(%1)%3 = Binary(%0, %2)%4 = Load()      &lt;- Load延迟%5 = Binary(%3, %4)%6 = Store(%5)优化后：%1 = Load()%0 = Load()%4 = Load()      &lt;- 提前Load%2 = Unary(%1)%3 = Binary(%0, %2)%5 = Binary(%3, %4)%6 = Store(%5)

4.2 实现代码void ReorderLoad(BasicBlock &amp;block) &#123;  // 从后向前遍历  for (auto iter = block.rbegin(); iter != block.rend(); ++iter) &#123;    auto obj = &amp;*iter;    if (!obj-&gt;IsLoad()) continue;        // 找到最早使用位置    NDObject *first_user = nullptr;    auto first_use_iter = block.end();        for (auto check = block.begin(); check != block.end(); ++check) &#123;      if (&amp;*check == obj) break;  // 到达Load自己            check-&gt;ForInput([&amp;obj, &amp;first_user, &amp;check](NDObject *op) &#123;        if (op == obj) &#123;          first_user = &amp;*check;          first_use_iter = check;        &#125;      &#125;);            if (first_user) break;    &#125;        if (first_user == nullptr) continue;        // 移动Load到使用位置之前    if (first_use_iter != block.begin()) &#123;      --first_use_iter;      block.Move(first_use_iter, obj);    &#125;  &#125;&#125;


五、CompactPeakLiveness优化5.1 活跃变量分析size_t MaxLive(BasicBlock &amp;bb) &#123;  size_t peak = 0;  size_t current_live = 0;  std::unordered_map&lt;NDObject *, int&gt; num_users;    auto try_deallocate = [&amp;num_users, &amp;current_live](NDObject *obj) &#123;    if (--num_users[obj] == 0) &#123;      current_live--;      num_users.erase(obj);    &#125;  &#125;;    // Load和Store总是占用一个变量  for (auto &amp;obj : bb) &#123;    if (obj.IsLoad()) &#123;      current_live++;      num_users[&amp;obj] = kNumUsersBig;  // 大数值表示永不释放    &#125;    if (obj.IsStore()) &#123;      current_live++;      num_users[obj.lhs_] = kNumUsersBig;    &#125;  &#125;    peak = current_live;    // 遍历SIMD操作  for (auto &amp;obj : bb) &#123;    if (!obj.IsSimd()) continue;        // 检查是否是新变量    if (num_users.find(&amp;obj) == num_users.end()) &#123;      num_users[&amp;obj] = bb.GetUserNum(&amp;obj);      ++current_live;    &#125;        // 检查是否可以Inplace    auto type = obj.GetObjectType();    bool need_update = true;        if (type == kUnary || type == kBinary || type == kBinaryS) &#123;      // Inplace优化      if (obj.lhs_ != nullptr &amp;&amp; num_users[obj.lhs_] == kNumUsers1) &#123;        need_update = false;      &#125;      if (obj.rhs_ != nullptr &amp;&amp; num_users[obj.rhs_] == kNumUsers1) &#123;        need_update = false;      &#125;    &#125;        if (need_update) &#123;      peak = std::max(peak, current_live);    &#125;        // 释放输入变量    obj.ForInput(try_deallocate);  &#125;    return peak;&#125;

5.2 启发式重排std::vector&lt;NDObject *&gt; ReorderObjectsHeuristic(BasicBlock &amp;bb) &#123;  // 计算优先级  std::unordered_map&lt;NDObject *, int64_t&gt; points;  std::unordered_map&lt;NDObject *, uint32_t&gt; heights;    constexpr int32_t B1 = 1;        // 高度权重  constexpr int32_t B2 = 1000;     // 可减少输入权重  constexpr int64_t B3 = 1000000;  // Load/Store权重    // 计算高度（到Store的最长路径）  for (auto iter = bb.rbegin(); iter != bb.rend(); ++iter) &#123;    auto obj = iter.get();    heights[obj] = 0;        for (auto user : bb.GetUsers(iter.get())) &#123;      heights[obj] = std::max(heights[obj], heights[user] + 1);    &#125;        // 计算优先级    if (!obj-&gt;IsSimd()) &#123;      points[obj] = B3;  // Load/Store最高优先级    &#125;        points[obj] += get_reducable_inputs_num(obj) * B2;    points[obj] -= heights[obj] * B1;  &#125;    // 拓扑排序  auto compare = [&amp;points](NDObject *a, NDObject *b) &#123;     return points[a] &lt; points[b];   &#125;;    std::priority_queue&lt;NDObject *, std::vector&lt;NDObject *&gt;, decltype(compare)&gt; pq(compare);  std::unordered_map&lt;NDObject *, uint32_t&gt; in_degrees;    // 计算入度  for (auto &amp;obj : bb) &#123;    in_degrees[&amp;obj] = GetInputsNum(&amp;obj);    if (in_degrees[&amp;obj] == 0) &#123;      pq.push(&amp;obj);    &#125;  &#125;    // 拓扑排序输出  std::vector&lt;NDObject *&gt; res;  res.reserve(bb.size());    while (!pq.empty()) &#123;    auto obj = pq.top();    pq.pop();    res.emplace_back(obj);        for (auto user : bb.GetUsers(obj)) &#123;      --in_degrees[user];      if (in_degrees[user] == 0) &#123;        pq.push(user);      &#125;    &#125;  &#125;    return res;&#125;

5.3 CompactPeakLiveness实现void CompactPeakLiveness(BasicBlock &amp;bb) &#123;  // 启发式重排  auto reordered = ReorderObjectsHeuristic(bb);    // 检查是否改善了峰值  auto old_peak = MaxLive(bb);    // 应用新顺序  bb.Export(reordered);    auto new_peak = MaxLive(bb);    // 如果没有改善，恢复原顺序  if (new_peak &gt;= old_peak) &#123;    // 恢复...  &#125;&#125;


六、EliminateReshape优化6.1 优化原理消除冗余的Reshape操作：
优化前：%0::(4,8) = Load()%1::(8,4) = Load()%2::(4,8) = Reshape(%1)   &lt;- 冗余Reshape%3::(4,8) = Binary(%0, %2)%4::(4,8) = Store(%3)优化后：%0::(8,4) = Load()%1::(8,4) = Load()%2::(8,4) = Binary(%0, %1)   &lt;- 直接使用原始Shape%3::(8,4) = Store(%2)

6.2 实现代码void EliminateReshape(BasicBlock &amp;bb) &#123;  std::vector&lt;NDObject *&gt; to_erase;    for (auto &amp;obj : bb) &#123;    if (obj.GetObjectType() != kReshape) continue;        auto input = obj.lhs_;    auto output_shape = obj.nd_.dims();    auto input_shape = input-&gt;nd_.dims();        // 检查是否是真正的Reshape（元素数相同）    int64_t output_elems = 1, input_elems = 1;    for (auto dim : output_shape) output_elems *= dim;    for (auto dim : input_shape) input_elems *= dim;        if (output_elems != input_elems) continue;        // 检查是否可以消除    // 条件：input只有一个用户（就是这个Reshape）    if (bb.GetUserNum(input) != 1) continue;        // 替换所有使用Reshape输出的地方为input    for (auto user : bb.GetUsers(&amp;obj)) &#123;      user-&gt;ForInput([&amp;obj, input](NDObject *&amp;op) &#123;        if (op == &amp;obj) &#123;          op = input;        &#125;      &#125;);    &#125;        to_erase.push_back(&amp;obj);  &#125;    // 删除冗余Reshape  for (auto obj : to_erase) &#123;    bb.Erase(obj);  &#125;&#125;


七、InsertRemovePad优化7.1 优化原理优化UB到GM的内存传输，将非连续内存段重组为连续布局：
优化前：UB: [data | pad | data | pad | data | pad]    ↓ 多次小传输GM: [data | pad | data | pad | data | pad]优化后：UB: [data | pad | data | pad | data | pad]    ↓ RemovePad重组UB: [data | data | data]    ↓ 单次大传输GM: [data | data | data]

7.2 实现代码void InsertRemovePad(BasicBlock &amp;block) &#123;  for (auto iter = block.begin(); iter != block.end(); ++iter) &#123;    auto obj = &amp;*iter;    if (!obj-&gt;IsStore()) continue;        auto input = obj-&gt;lhs_;    if (input == nullptr || input-&gt;IsLoad()) continue;        // 检查是否有Padding    auto &amp;strides = input-&gt;nd_.strides();    auto &amp;dims = input-&gt;nd_.dims();        bool has_padding = false;    for (size_t i = 0; i &lt; dims.size(); ++i) &#123;      if (strides[i] != (i == dims.size() - 1 ? 1 : strides[i + 1] * dims[i + 1])) &#123;        has_padding = true;        break;      &#125;    &#125;        if (!has_padding) continue;        // 插入RemovePad操作    auto remove_pad = new NDRemovePad(input);    block.Insert(iter, remove_pad);    obj-&gt;lhs_ = remove_pad;  &#125;&#125;


八、Pass执行流程8.1 默认Pass列表namespace dvm::pass &#123;std::vector&lt;Pass&gt; passes = &#123;  ReorderStore,  ReorderLoad,  CompactPeakLiveness,  EliminateReshape,  InsertRemovePad,&#125;;&#125;  // namespace dvm::pass

8.2 Pass执行void RunPasses(BasicBlock &amp;block) &#123;  for (auto pass : passes) &#123;    pass(block);  &#125;&#125;// 自定义Pass列表void RunCustomPasses(BasicBlock &amp;block, const std::vector&lt;std::string&gt; &amp;pass_names) &#123;  static const std::unordered_map&lt;std::string, Pass&gt; pass_map = &#123;    &#123;&quot;PrintPeakLive&quot;, PrintPeakLive&#125;,    &#123;&quot;ReorderStore&quot;, ReorderStore&#125;,    &#123;&quot;ReorderLoad&quot;, ReorderLoad&#125;,    &#123;&quot;CompactPeakLiveness&quot;, CompactPeakLiveness&#125;,    &#123;&quot;EliminateReshape&quot;, EliminateReshape&#125;,    &#123;&quot;InsertRemovePad&quot;, InsertRemovePad&#125;,  &#125;;    for (auto name : pass_names) &#123;    pass_map.at(name)(block);  &#125;&#125;

