二、DVM Tiling策略2.1 Tile参数struct TileParam &#123;  uint64_t tile_num;    // Tile总数  uint64_t tile_size;   // 每个Tile的元素数  uint64_t xbuf_size;   // UB缓冲区大小  uint64_t lead_align;  // 前导对齐  int max_type;         // 最大数据类型  int min_type;         // 最小数据类型&#125;;

2.2 Tile计算流程void VectorKernel::PrepareTiling() &#123;  // 1. 构建计算域  BuildDomain();    // 2. 计算Tile数量  auto &amp;dims = dom_-&gt;nd_.dims();  tile_num_ = 1;  for (auto dim : dims) &#123;    tile_num_ *= dim;  &#125;    // 3. 计算Tile大小  CalculateTileSize();    // 4. 计算UB需求  CalculateUBSize();&#125;

2.3 Tile大小计算void VectorKernel::CalculateTileSize() &#123;  // 获取UB容量  uint64_t ub_capacity = GetUBCapacity();    // 计算最大Tile大小  uint64_t max_tile = ub_capacity / (ITEM_SIZE[max_type_] * max_live_vars_);    // 考虑对齐  uint64_t align = 32 / ITEM_SIZE[max_type_];  tile_size_ = (max_tile / align) * align;    // 限制Tile数量上限  uint64_t max_tiles = GetMaxTiles();  if (tile_num_ &gt; max_tiles) &#123;    tile_size_ = CeilDiv(tile_num_, max_tiles);    tile_num_ = max_tiles;  &#125;&#125;

2.4 维度Tilingstruct DimTile &#123;  int dim;              // 维度索引  int64_t tile_size;    // Tile大小  int64_t num_tiles;    // Tile数量  int64_t tail_size;    // 尾部大小&#125;;void SetTile(int start, int end, int64_t num, int64_t factor) &#123;  tiles_.clear();    for (int dim = start; dim &lt; end; ++dim) &#123;    DimTile tile;    tile.dim = dim;    tile.tile_size = factor &gt; 0 ? factor : dom_-&gt;dims()[dim];    tile.num_tiles = CeilDiv(dom_-&gt;dims()[dim], tile.tile_size);    tile.tail_size = dom_-&gt;dims()[dim] % tile.tile_size;        tiles_.push_back(tile);  &#125;    // 更新Tile总数  tile_num_ = 1;  for (auto &amp;tile : tiles_) &#123;    tile_num_ *= tile.num_tiles;  &#125;&#125;


三、UB内存管理3.1 UB布局规划void VectorKernel::PlanUBLayout() &#123;  // 静态分配  static_xbuf_ = 0;    // 1. 分配Load缓冲区  for (auto op : objects_) &#123;    if (op-&gt;IsLoad()) &#123;      op-&gt;xbuf_ = static_xbuf_;      static_xbuf_ += tile_size_ * ITEM_SIZE[op-&gt;type_id_];    &#125;  &#125;    // 2. 分配中间结果缓冲区  for (auto op : objects_) &#123;    if (op-&gt;IsSimd() &amp;&amp; !op-&gt;IsStore()) &#123;      if (op-&gt;xbuf_ == 0) &#123;        // 尝试复用        if (!TryReuseXBuf(op)) &#123;          op-&gt;xbuf_ = static_xbuf_;          static_xbuf_ += tile_size_ * ITEM_SIZE[op-&gt;type_id_];        &#125;      &#125;    &#125;  &#125;    // 3. 分配Store缓冲区  for (auto op : objects_) &#123;    if (op-&gt;IsStore()) &#123;      op-&gt;xbuf_ = op-&gt;lhs_-&gt;xbuf_;    &#125;  &#125;    xbuf_size_ = static_xbuf_;&#125;

3.2 内存复用策略bool TryReuseXBuf(NDObject *op) &#123;  // 策略1：Inplace复用  if (op-&gt;flags_ &amp; F_IP) &#123;    if (op-&gt;lhs_ &amp;&amp; op-&gt;lhs_-&gt;flags_ &amp; OBJ_FLAG_FREE_LHS) &#123;      op-&gt;xbuf_ = op-&gt;lhs_-&gt;xbuf_;      return true;    &#125;    if (op-&gt;rhs_ &amp;&amp; op-&gt;rhs_-&gt;flags_ &amp; OBJ_FLAG_FREE_RHS) &#123;      op-&gt;xbuf_ = op-&gt;rhs_-&gt;xbuf_;      return true;    &#125;  &#125;    // 策略2：从空闲列表分配  auto xbuf = free_xbuf_.Pop(op);  if (xbuf != 0) &#123;    op-&gt;xbuf_ = xbuf;    return true;  &#125;    return false;&#125;

3.3 空闲列表管理class FreeXBufList &#123; public:  uint64_t Pop(NDObject *user) &#123;    if (list_.empty()) &#123;      return 0;    &#125;        // 找到最早可用的xbuf    for (auto it = list_.begin(); it != list_.end(); ++it) &#123;      if (it-&gt;first &lt;= user-&gt;index_) &#123;        auto xbuf = it-&gt;second;        list_.erase(it);        return xbuf;      &#125;    &#125;        return 0;  &#125;    void Push(uint64_t xbuf, NDObject *owner) &#123;    // 找到所有用户中最晚的索引    uint64_t last_use = owner-&gt;index_;    for (auto user : GetUsers(owner)) &#123;      last_use = std::max(last_use, user-&gt;index_);    &#125;        list_.emplace_back(last_use, xbuf);  &#125;   private:  std::list&lt;std::pair&lt;uint64_t, uint64_t&gt;&gt; list_;  // (last_use, xbuf)&#125;;


四、活跃变量分析4.1 活跃变量定义活跃变量：在某个程序点之后还会被使用的变量程序点：Load -&gt; Binary -&gt; Binary -&gt; Store        │        │         │         │活跃变量：  &#123;L0&#125;    &#123;L0,L1&#125;  &#123;L0,L1&#125;   &#123;S0&#125;

4.2 活跃变量计算size_t CalculatePeakLiveness(VectorKernel &amp;kernel) &#123;  size_t peak = 0;  size_t current = 0;  std::unordered_map&lt;NDObject *, int&gt; ref_count;    // 计算引用计数  for (auto op : kernel.objects_) &#123;    op-&gt;ForInput([&amp;ref_count](NDObject *input) &#123;      ref_count[input]++;    &#125;);  &#125;    // 遍历计算峰值  for (auto op : kernel.objects_) &#123;    // 新产生变量    if (!op-&gt;IsLoad() &amp;&amp; !op-&gt;IsStore()) &#123;      current++;    &#125;        peak = std::max(peak, current);        // 释放不再使用的变量    op-&gt;ForInput([&amp;](NDObject *input) &#123;      if (--ref_count[input] == 0) &#123;        current--;      &#125;    &#125;);  &#125;    return peak;&#125;

4.3 峰值优化void OptimizePeakLiveness(BasicBlock &amp;bb) &#123;  // 使用启发式重排  auto new_order = ReorderForMinPeak(bb);    // 检查是否改善  auto old_peak = CalculatePeakLiveness(bb);  bb.ApplyOrder(new_order);  auto new_peak = CalculatePeakLiveness(bb);    // 如果没有改善，恢复原顺序  if (new_peak &gt;= old_peak) &#123;    bb.RestoreOrder();  &#125;&#125;


五、多核并行策略5.1 Block维度计算uint32_t VectorKernel::CompactBlockDim(uint64_t core_limit) &#123;  // 计算每个核心处理的Tile数  uint64_t tiles_per_core = CeilDiv(tile_num_, core_limit);    // 计算实际需要的核心数  uint32_t block_dim = CeilDiv&lt;uint32_t&gt;(tile_num_, tiles_per_core);    // 限制最大核心数  return std::min(block_dim, static_cast&lt;uint32_t&gt;(core_limit));&#125;

5.2 负载均衡void BalanceWorkload(uint64_t tile_num, uint64_t block_dim,                     uint64_t &amp;body_tiles, uint64_t &amp;tail_blocks) &#123;  // 计算基本分配  body_tiles = CeilDiv(tile_num, block_dim);    // 计算尾部块数  uint64_t total_with_tail = body_tiles * block_dim;  tail_blocks = total_with_tail - tile_num;&#125;

5.3 并行执行示意Tile总数 = 100，核心数 = 8方案1（不均衡）：Core0: 13 tilesCore1: 13 tilesCore2: 12 tilesCore3: 12 tilesCore4: 13 tilesCore5: 12 tilesCore6: 12 tilesCore7: 13 tiles方案2（均衡）：body_tiles = 13tail_blocks = 4Core0-3: 12 tiles (body_tiles - 1)Core4-7: 13 tiles (body_tiles)


六、MatMul Tiling策略6.1 MatMul分块struct MatMulTile &#123;  uint64_t M_tile;    // M维度Tile大小  uint64_t N_tile;    // N维度Tile大小  uint64_t K_tile;    // K维度Tile大小&#125;;MatMulTile CalculateMatMulTile(uint64_t M, uint64_t N, uint64_t K,                                uint64_t ub_size) &#123;  MatMulTile tile;    // L1 Cache大小限制  uint64_t l1_size = GetL1CacheSize();    // 计算最大分块  // A矩阵：M_tile * K_tile  // B矩阵：K_tile * N_tile  // C矩阵：M_tile * N_tile    uint64_t elem_size = 2;  // FP16  uint64_t max_mn = static_cast&lt;uint64_t&gt;(std::sqrt(l1_size / elem_size / 3));    tile.M_tile = std::min(M, max_mn);  tile.N_tile = std::min(N, max_mn);  tile.K_tile = std::min(K, l1_size / elem_size / (tile.M_tile + tile.N_tile));    return tile;&#125;

6.2 Cube核并行void CubeKernel::CalculateBlockDim() &#123;  // M维度分块  uint64_t m_tiles = CeilDiv(M_, M_tile_);    // N维度分块  uint64_t n_tiles = CeilDiv(N_, N_tile_);    // 总分块数  uint64_t total_tiles = m_tiles * n_tiles;    // 核心数  block_dim_ = std::min(total_tiles, GetAvailableCores());&#125;


七、Reduce Tiling策略7.1 Reduce维度处理void ReduceOp::CalculateTiling() &#123;  // Reduce维度  auto &amp;reduce_dims = reduce_dims_;    // 非Reduce维度  auto &amp;keep_dims = keep_dims_;    // 计算Tile  // 非Reduce维度作为并行维度  tile_num_ = 1;  for (auto dim : keep_dims) &#123;    tile_num_ *= shape_[dim];  &#125;    // Reduce维度作为迭代维度  reduce_iter_ = 1;  for (auto dim : reduce_dims) &#123;    reduce_iter_ *= shape_[dim];  &#125;&#125;

7.2 Reduce访问模式// 单维度Reducevoid VisitRed1(uint64_t tile, uint64_t reduce_dim, uint64_t reduce_size) &#123;  uint64_t outer_idx = tile / reduce_size;  uint64_t inner_idx = tile % reduce_size;    // 计算数据偏移  uint64_t offset = outer_idx * reduce_size * stride_ + inner_idx;    ProcessReduce(offset);&#125;// 多维度Reducevoid VisitRed2(uint64_t tile, uint64_t dim0, uint64_t dim1,               uint64_t size0, uint64_t size1) &#123;  uint64_t idx0 = tile % size0;  uint64_t idx1 = (tile / size0) % size1;  uint64_t outer = tile / (size0 * size1);    uint64_t offset = CalculateOffset(outer, idx0, idx1);    ProcessReduce(offset);&#125;


八、通信算子优化8.1 AllReduce Tilingvoid AllReduceOp::CalculateTiling() &#123;  // 数据大小  uint64_t data_size = NumElements() * ITEM_SIZE[type_];    // 通信缓冲区大小限制  uint64_t comm_buf_size = GetCommBufferSize();    // 计算分块数  if (data_size &lt;= comm_buf_size) &#123;    tile_num_ = 1;    tile_size_ = data_size;  &#125; else &#123;    tile_num_ = CeilDiv(data_size, comm_buf_size);    tile_size_ = comm_buf_size;  &#125;&#125;

8.2 通信与计算重叠void ExecuteAllReduceOverlap(uint8_t *code, void *workspace) &#123;  for (uint64_t tile = 0; tile &lt; tile_num_; ++tile) &#123;    // 1. 计算当前Tile    ExecuteCompute(code, workspace, tile);        // 2. 异步通信上一个Tile    if (tile &gt; 0) &#123;      AllReduceAsync(workspace, tile - 1);    &#125;        // 3. 等待上上个Tile通信完成    if (tile &gt; 1) &#123;      WaitAllReduce(tile - 2);    &#125;  &#125;    // 等待最后两个Tile  WaitAllReduce(tile_num_ - 2);  WaitAllReduce(tile_num_ - 1);&#125;


九、性能调优9.1 Tuning框架class Tuner &#123; public:  virtual void Tune(CubeOp *cube) = 0;   protected:  void UpdateBest(const TuneResult &amp;result);  TuneResult best_;&#125;;// 在线Tuningclass OnlineTuner : public Tuner &#123; public:  void Tune(CubeOp *cube) override &#123;    // 尝试多种配置    for (auto config : configs_) &#123;      auto result = RunWithConfig(cube, config);      if (result.time &lt; best_.time) &#123;        UpdateBest(result);      &#125;    &#125;        // 应用最优配置    ApplyBest(cube);  &#125;&#125;;

