2.2 AllReduce构图// Python接口@dvm.kerneldef allreduce_example(k, x):    x = k.load(x, dvm.float32)    y = k.allreduce(&quot;sum&quot;, x)    return k.store(y)// C++接口auto x = kernel.Load(dev_x, &amp;shape_ref, dvm::kFloat32);auto y = kernel.AllReduce(dvm::kSum, x);auto out = kernel.Store(dev_out, y);

2.3 AllReduce代码生成uint64_t CommOp::Emit(VectorKernel &amp;kernel) &#123;  switch (comm_type_) &#123;    case kAllReduce:      return EmitAllReduce(kernel);    case kAllGather:      return EmitAllGather(kernel);    case kReduceScatter:      return EmitReduceScatter(kernel);    default:      return 0;  &#125;&#125;uint64_t CommOp::EmitAllReduce(VectorKernel &amp;kernel) &#123;  vComm op;  op.xd = xbuf_;  op.xn = lhs_-&gt;xbuf_;  op.comm_type = kAllReduce;  op.red_type = red_type_;  op.comm_size = comm_group_.size();  op.comm_rank = GetCommRank();    return vComm::Encode(insn_, V_ALL_REDUCE, op);&#125;

2.4 AllReduce虚拟机执行__aicore__ void ExecAllReduce(vComm *op) &#123;  auto data = reinterpret_cast&lt;float *&gt;(op-&gt;xn);  auto result = reinterpret_cast&lt;float *&gt;(op-&gt;xd);  uint64_t size = op-&gt;size;    switch (op-&gt;red_type) &#123;    case kSum:      // Ring AllReduce实现      RingAllReduceSum(data, result, size, op-&gt;comm_size, op-&gt;comm_rank);      break;          case kMax:      RingAllReduceMax(data, result, size, op-&gt;comm_size, op-&gt;comm_rank);      break;          case kMin:      RingAllReduceMin(data, result, size, op-&gt;comm_size, op-&gt;comm_rank);      break;  &#125;&#125;

2.5 Ring AllReduce算法__aicore__ void RingAllReduceSum(float *send_buf, float *recv_buf,                                  uint64_t size, int comm_size, int rank) &#123;  uint64_t chunk_size = size / comm_size;    // Step 1: Scatter-Reduce  for (int step = 0; step &lt; comm_size - 1; ++step) &#123;    int send_chunk = (rank - step + comm_size) % comm_size;    int recv_chunk = (rank - step - 1 + comm_size) % comm_size;        // 发送当前块    SendAsync(send_buf + send_chunk * chunk_size, chunk_size,              (rank + 1) % comm_size);        // 接收并累加    RecvAsync(recv_buf + recv_chunk * chunk_size, chunk_size,              (rank - 1 + comm_size) % comm_size);        WaitSendRecv();        // 累加到发送缓冲区    for (uint64_t i = 0; i &lt; chunk_size; ++i) &#123;      send_buf[recv_chunk * chunk_size + i] += recv_buf[recv_chunk * chunk_size + i];    &#125;  &#125;    // Step 2: All-Gather  for (int step = 0; step &lt; comm_size - 1; ++step) &#123;    int send_chunk = (rank - step + 1 + comm_size) % comm_size;    int recv_chunk = (rank - step + comm_size) % comm_size;        SendAsync(send_buf + send_chunk * chunk_size, chunk_size,              (rank + 1) % comm_size);    RecvAsync(recv_buf + recv_chunk * chunk_size, chunk_size,              (rank - 1 + comm_size) % comm_size);        WaitSendRecv();        // 复制到发送缓冲区    for (uint64_t i = 0; i &lt; chunk_size; ++i) &#123;      send_buf[recv_chunk * chunk_size + i] = recv_buf[recv_chunk * chunk_size + i];    &#125;  &#125;    // 复制结果  for (uint64_t i = 0; i &lt; size; ++i) &#123;    recv_buf[i] = send_buf[i];  &#125;&#125;


