3.2 AllGather代码生成uint64_t CommOp::EmitAllGather(VectorKernel &amp;kernel) &#123;  vComm op;  op.xd = xbuf_;  op.xn = lhs_-&gt;xbuf_;  op.comm_type = kAllGather;  op.comm_size = comm_group_.size();  op.comm_rank = GetCommRank();    // 输出Shape扩展  auto &amp;input_shape = lhs_-&gt;nd_.dims();  std::vector&lt;int64_t&gt; output_shape(input_shape);  output_shape[0] *= comm_group_.size();    return vComm::Encode(insn_, V_ALL_GATHER, op);&#125;

3.3 AllGather虚拟机执行__aicore__ void ExecAllGather(vComm *op) &#123;  auto send_buf = reinterpret_cast&lt;float *&gt;(op-&gt;xn);  auto recv_buf = reinterpret_cast&lt;float *&gt;(op-&gt;xd);  uint64_t chunk_size = op-&gt;size;  int comm_size = op-&gt;comm_size;  int rank = op-&gt;comm_rank;    // 先复制自己的数据  for (uint64_t i = 0; i &lt; chunk_size; ++i) &#123;    recv_buf[rank * chunk_size + i] = send_buf[i];  &#125;    // Ring AllGather  for (int step = 0; step &lt; comm_size - 1; ++step) &#123;    int send_chunk = (rank - step + comm_size) % comm_size;    int recv_chunk = (rank - step - 1 + comm_size) % comm_size;        SendAsync(recv_buf + send_chunk * chunk_size, chunk_size,              (rank + 1) % comm_size);    RecvAsync(recv_buf + recv_chunk * chunk_size, chunk_size,              (rank - 1 + comm_size) % comm_size);        WaitSendRecv();  &#125;&#125;


