4.3 ReduceScatter虚拟机执行__aicore__ void ExecReduceScatter(vComm *op) &#123;  auto send_buf = reinterpret_cast&lt;float *&gt;(op-&gt;xn);  auto recv_buf = reinterpret_cast&lt;float *&gt;(op-&gt;xd);  uint64_t chunk_size = op-&gt;size;  int comm_size = op-&gt;comm_size;  int rank = op-&gt;comm_rank;    // Ring ReduceScatter (Scatter-Reduce阶段)  for (int step = 0; step &lt; comm_size - 1; ++step) &#123;    int send_chunk = (rank - step + comm_size) % comm_size;    int recv_chunk = (rank - step - 1 + comm_size) % comm_size;        SendAsync(send_buf + send_chunk * chunk_size, chunk_size,              (rank + 1) % comm_size);    RecvAsync(send_buf + recv_chunk * chunk_size, chunk_size,              (rank - 1 + comm_size) % comm_size);        WaitSendRecv();        // 累加    for (uint64_t i = 0; i &lt; chunk_size; ++i) &#123;      send_buf[recv_chunk * chunk_size + i] +=           send_buf[recv_chunk * chunk_size + i];    &#125;  &#125;    // 复制结果  int result_chunk = (rank + 1) % comm_size;  for (uint64_t i = 0; i &lt; chunk_size; ++i) &#123;    recv_buf[i] = send_buf[result_chunk * chunk_size + i];  &#125;&#125;


